const [loading, setLoading] = useState(false);
const inFlight = useRef(false); // two quick taps both see loading=false

async function submit() {
  if (inFlight.current) return;
  inFlight.current = true;
  setLoading(true);
  try {
    await placeOrder(cart);
  } finally {
    inFlight.current = false;
    setLoading(false);
  }
}

return (
  <button onClick={submit} disabled={loading} aria-busy={loading} style={{ minWidth: 140 }}>
    {loading ? <Spinner /> : "Place order"}
  </button>
);
